"use client"

import * as React from "react"
import { Tooltip as TooltipPrimitive } from "radix-ui"
import { cn } from "@/lib/utils"
import { MinecraftSurface } from "./minecraft-surface"
import { MinecraftText } from "./minecraft-text"
import { minecraftTooltipSprites as sprites } from "./minecraft-tooltip-sprites"
import { minecraftTextWidth, wrapMinecraftTooltip } from "./minecraft-tooltip-layout"
import { MinecraftTooltipSurface } from "./minecraft-tooltip-paint"
import "./minecraft-tooltip.css"

function TooltipProvider({ delayDuration = 0, ...props }: React.ComponentProps<typeof TooltipPrimitive.Provider>) {
  return <TooltipPrimitive.Provider data-slot="tooltip-provider" delayDuration={delayDuration} {...props} />
}
function Tooltip(props: React.ComponentProps<typeof TooltipPrimitive.Root>) { return <TooltipPrimitive.Root data-slot="tooltip" {...props} /> }
function TooltipTrigger(props: React.ComponentProps<typeof TooltipPrimitive.Trigger>) { return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} /> }

function TooltipContent({ className, sideOffset = 0, scale = 2, maxWidth = 170, children, asChild, style, ref, ...props }:
  React.ComponentProps<typeof TooltipPrimitive.Content> & { scale?: 1 | 2 | 3; maxWidth?: number }) {
  const [node, setNode] = React.useState<HTMLDivElement | null>(null)
  const [available, setAvailable] = React.useState(maxWidth)
  React.useImperativeHandle(ref, () => node!, [node])
  React.useLayoutEffect(() => {
    if (!node) return
    const measure = () => {
      const physical = parseFloat(getComputedStyle(node).getPropertyValue("--radix-tooltip-content-available-width")) || window.innerWidth
      setAvailable(Math.max(1, Math.min(maxWidth, Math.floor(physical / scale - 24))))
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(node)
    window.addEventListener("resize", measure)
    return () => { observer.disconnect(); window.removeEventListener("resize", measure) }
  }, [node, maxWidth, scale])
  const skin = (content: React.ReactNode) => {
    const plain = (typeof content === "string" || typeof content === "number") && /^[\x20-\x7e\n]*$/.test(String(content)) ? String(content) : undefined
    const lines = plain == null ? undefined : wrapMinecraftTooltip(plain, Math.min(maxWidth, available))
    const width = lines ? Math.max(0, ...lines.map(minecraftTextWidth)) + 24 : undefined
    const height = lines ? (lines.length === 1 ? 8 : lines.length * 10) + 24 : undefined
    return <>{width && height ? <MinecraftTooltipSurface width={width} height={height} scale={scale} /> : <><MinecraftSurface sprite={sprites.background} /><MinecraftSurface sprite={sprites.frame} /></>}
      <div className="mc-tooltip-lines">{lines ? lines.map((line, index) => <MinecraftText className="mc-tooltip-line" key={index}>{line}</MinecraftText>) : content}</div>
    </>
  }
  const plain = typeof children === "string" || typeof children === "number" ? String(children) :
    asChild && React.isValidElement<{ children?: React.ReactNode }>(children) && typeof children.props.children === "string" ? children.props.children : undefined
  const lines = plain == null || !/^[\x20-\x7e\n]*$/.test(plain) ? undefined : wrapMinecraftTooltip(plain, Math.min(maxWidth, available))
  const width = lines ? Math.max(0, ...lines.map(minecraftTextWidth)) + 24 : undefined
  const height = lines ? (lines.length === 1 ? 8 : lines.length * 10) + 24 : undefined
  const content = asChild && React.isValidElement<{ children?: React.ReactNode }>(children)
    ? React.cloneElement(children, {}, skin(children.props.children)) : skin(children)
  return <TooltipPrimitive.Portal forceMount={props.forceMount}>
    <TooltipPrimitive.Content ref={setNode} data-slot="tooltip-content" sideOffset={sideOffset} asChild={asChild}
      className={cn("mc-tooltip", className)} style={{ "--mc-scale": scale, "--mc-tooltip-max": maxWidth, "--mc-tooltip-width": width, "--mc-tooltip-height": height, ...style } as React.CSSProperties} {...props}>
      {content}
    </TooltipPrimitive.Content>
  </TooltipPrimitive.Portal>
}
export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider }

@layer theme, base, components, utilities;
@layer components {
  .mc-tooltip {
    --mc-pixel: calc(1px * var(--mc-scale, 2));
    --mc-ink: #fff;
    --mc-shadow: #3f3f3f;
    position: relative;
    z-index: 50;
    box-sizing: border-box;
    width: calc(var(--mc-tooltip-width) * var(--mc-pixel));
    height: calc(var(--mc-tooltip-height) * var(--mc-pixel));
    max-width: min(var(--radix-tooltip-content-available-width, 100vw), calc((var(--mc-tooltip-max, 170) + 24) * var(--mc-pixel)));
    padding: calc(12 * var(--mc-pixel));
    background: transparent;
    border: 0;
    border-radius: 0;
    outline: 0;
    color: #fff;
    font-family: "Minecraft Pilot 26.2", monospace;
    font-size: calc(8 * var(--mc-pixel));
    line-height: calc(10 * var(--mc-pixel));
    image-rendering: pixelated;
  }
  .mc-tooltip-lines { position: relative; display: flex; flex-direction: column; align-items: flex-start; white-space: pre-wrap; overflow-wrap: anywhere; }
  .mc-tooltip-line { height: calc(10 * var(--mc-pixel)); flex-shrink: 0; }
  .mc-tooltip-line:first-child:not(:last-child) { margin-bottom: calc(2 * var(--mc-pixel)); }
}

import { minecraftGlyphs } from "./minecraft-font"
export const minecraftTextWidth = (text: string) => Array.from(text).reduce((sum, char) => sum + (minecraftGlyphs[char.charCodeAt(0) - 32]?.[2] ?? 6), 0)

export function wrapMinecraftTooltip(text: string, maxWidth: number) {
  const lines: string[] = []
  for (const paragraph of text.split("\n")) {
    let remaining = paragraph
    while (remaining.length && minecraftTextWidth(remaining) > maxWidth) {
      let count = 0, width = 0, lastSpace = -1
      while (count < remaining.length) {
        const next = minecraftTextWidth(remaining[count])
        if (remaining[count] === " ") lastSpace = count
        if (width + next > maxWidth && count > 0) break
        width += next; count++
      }
      if (lastSpace >= 0) { lines.push(remaining.slice(0, lastSpace)); remaining = remaining.slice(lastSpace + 1) }
      else { lines.push(remaining.slice(0, Math.max(1, count))); remaining = remaining.slice(Math.max(1, count)) }
    }
    lines.push(remaining)
  }
  return lines
}

import * as React from "react"
import { minecraftTooltipSprites as sprites } from "./minecraft-tooltip-sprites"
import { MinecraftSurface } from "./minecraft-surface"
import { gpuTooltipPixels } from "./minecraft-tooltip-gpu"

function solidBackdrop(node: HTMLElement) {
  const bounds = node.getBoundingClientRect()
  const under = document.elementsFromPoint(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2).find(element => !node.contains(element) && !element.hasAttribute("data-radix-popper-content-wrapper"))
  if (!under) return undefined
  const layers: number[][] = []
  for (let element: Element | null = under; element; element = element.parentElement) {
    const style = getComputedStyle(element)
    if (style.backgroundImage !== "none") return undefined
    const rgba = style.backgroundColor.match(/[\d.]+/g)?.map(Number)
    if (rgba && rgba.length >= 3) {
      const alpha = rgba[3] ?? 1
      layers.push([...rgba.slice(0, 3), alpha])
      if (alpha === 1) break
    }
  }
  const color = [255, 255, 255]
  for (const layer of layers.reverse()) for (let c = 0; c < 3; c++) color[c] = Math.round(layer[c] * layer[3] + color[c] * (1 - layer[3]))
  // Flatten only a uniform backdrop. One center sample cannot establish what
  // lies beneath the transparent padding or shadow around the native frame.
  for (const element of document.body.querySelectorAll("*")) {
    if (node.contains(element) || element.contains(node) || element === under || element.contains(under)) continue
    const box = element.getBoundingClientRect()
    if (!box.width || !box.height || box.right <= bounds.left || box.left >= bounds.right || box.bottom <= bounds.top || box.top >= bounds.bottom) continue
    const style = getComputedStyle(element)
    if (style.visibility !== "visible" || style.display === "none") continue
    const ownText = Array.from(element.childNodes).some(child => child.nodeType === Node.TEXT_NODE && child.textContent?.trim())
    const background = style.backgroundColor.match(/[\d.]+/g)?.map(Number)
    const differentColor = background && (background[3] ?? 1) > 0 && background.slice(0, 3).some((channel, index) => channel !== color[index])
    if (ownText || differentColor || style.backgroundImage !== "none" || style.boxShadow !== "none" || style.filter !== "none" || Number(style.opacity) < 1 || [style.borderTopWidth, style.borderRightWidth, style.borderBottomWidth, style.borderLeftWidth].some(value => parseFloat(value) > 0) || ["IMG", "CANVAS", "INPUT", "VIDEO", "SVG"].includes(element.tagName)) return undefined
  }
  return color
}

export function MinecraftTooltipSurface({ width, height, scale }: { width: number; height: number; scale: number }) {
  const canvas = React.useRef<HTMLCanvasElement>(null)
  const [painted, setPainted] = React.useState(false)
  React.useLayoutEffect(() => {
    const node = canvas.current!, parent = node.parentElement!
    let signature = ""
    const paint = () => {
      const backdrop = solidBackdrop(parent)
      if (!backdrop) { signature = ""; setPainted(false); return }
      const bounds = parent.getBoundingClientRect()
      const next = [backdrop, bounds.x, bounds.y, innerWidth, innerHeight].join(",")
      if (next === signature) return
      signature = next
      const w = width * scale, h = height * scale
      node.width = w; node.height = h
      const pixels = gpuTooltipPixels(w, h, scale, backdrop, bounds.x, bounds.y)
      if (!pixels) { setPainted(false); return }
      node.getContext("2d")!.putImageData(new ImageData(pixels, w, h), 0, 0)
      node.dataset.mcBackdrop = backdrop.join(",")
      node.dataset.mcLocation = [bounds.x, bounds.y].join(",")
      setPainted(true)
    }
    const frame = requestAnimationFrame(paint), timer = window.setInterval(paint, 100)
    return () => { cancelAnimationFrame(frame); clearInterval(timer) }
  }, [width, height, scale])
  return <>
    {!painted && <><MinecraftSurface sprite={sprites.background} /><MinecraftSurface sprite={sprites.frame} /></>}
    <canvas ref={canvas} aria-hidden="true" data-mc-tooltip-painted={painted} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none", visibility: painted ? "visible" : "hidden" }} />
  </>
}

import { minecraftTooltipSprites as sprites, minecraftTooltipAtlas as atlas } from "./minecraft-tooltip-sprites"

/** Original atlas coordinates and nearest sampling, with native source-alpha blending. */
export function gpuTooltipPixels(width: number, height: number, scale: number, backdrop: readonly number[], x: number, y: number) {
  const canvas = document.createElement("canvas")
  const viewportWidth = window.innerWidth, viewportHeight = window.innerHeight
  canvas.width = viewportWidth; canvas.height = viewportHeight
  const gl = canvas.getContext("webgl", { alpha: false, antialias: false, preserveDrawingBuffer: true })
  if (!gl) return undefined
  const shader = (kind: number, source: string) => {
    const value = gl.createShader(kind)!
    gl.shaderSource(value, source); gl.compileShader(value)
    if (!gl.getShaderParameter(value, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(value) ?? "Tooltip shader failed")
    return value
  }
  const program = gl.createProgram()!
  const vertex = shader(gl.VERTEX_SHADER, "attribute vec2 position; attribute vec2 uv; varying vec2 coord; uniform vec2 projection; void main(){gl_Position=vec4(position*projection+vec2(-1.,1.),0.,1.);coord=uv;}")
  const fragment = shader(gl.FRAGMENT_SHADER, "precision highp float; varying vec2 coord; uniform sampler2D atlas; void main(){gl_FragColor=texture2D(atlas,coord);}")
  gl.attachShader(program, vertex); gl.attachShader(program, fragment); gl.linkProgram(program); gl.useProgram(program)
  const texture = gl.createTexture()!
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, atlas.width, atlas.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, null)
  for (const name of ["background", "frame"] as const) {
    const sprite = sprites[name], location = atlas.locations[name]
    const rgba = Uint8Array.from(atob(sprite.rgba), c => c.charCodeAt(0))
    gl.texSubImage2D(gl.TEXTURE_2D, 0, location.x, location.y, sprite.width, sprite.height, gl.RGBA, gl.UNSIGNED_BYTE, rgba)
  }
  const buffer = gl.createBuffer()!
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
  for (const [name, offset] of [["position", 0], ["uv", 8]] as const) {
    const location = gl.getAttribLocation(program, name)
    gl.enableVertexAttribArray(location); gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 16, offset)
  }
  gl.uniform2f(gl.getUniformLocation(program, "projection"), 2 / viewportWidth, -2 / viewportHeight)
  gl.viewport(0, 0, viewportWidth, viewportHeight)
  gl.clearColor(backdrop[0] / 255, backdrop[1] / 255, backdrop[2] / 255, 1); gl.clear(gl.COLOR_BUFFER_BIT)
  gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA)
  const originX = Math.round(x), originY = Math.round(y)
  const draw = (dx: number, dy: number, w: number, h: number, u: number, v: number, sw: number, sh: number) => {
    const x = originX + dx, y = originY + dy
    const a = [x, y, u / atlas.width, v / atlas.height], b = [x, y + h, u / atlas.width, (v + sh) / atlas.height], c = [x + w, y + h, (u + sw) / atlas.width, (v + sh) / atlas.height], d = [x + w, y, (u + sw) / atlas.width, v / atlas.height]
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([...a, ...b, ...c, ...a, ...c, ...d]), gl.STREAM_DRAW)
    gl.drawArrays(gl.TRIANGLES, 0, 6)
  }
  for (const name of ["background", "frame"] as const) {
    const sprite = sprites[name], location = atlas.locations[name]
    const border = sprite.border.left, sizes = [border, 100 - border * 2, border]
    const widths = [border * scale, width - border * scale * 2, border * scale], heights = [border * scale, height - border * scale * 2, border * scale]
    for (let row = 0, y = 0, sy = 0; row < 3; y += heights[row], sy += sizes[row++]) for (let col = 0, x = 0, sx = 0; col < 3; x += widths[col], sx += sizes[col++]) {
      if (sprite.stretch) draw(x, y, widths[col], heights[row], sx + location.x, sy + location.y, sizes[col], sizes[row])
      else for (let dy = 0; dy < heights[row]; dy += sizes[row] * scale) for (let dx = 0; dx < widths[col]; dx += sizes[col] * scale) {
        const w = Math.min(sizes[col] * scale, widths[col] - dx), h = Math.min(sizes[row] * scale, heights[row] - dy)
        draw(x + dx, y + dy, w, h, sx + location.x, sy + location.y, w / scale, h / scale)
      }
    }
  }
  const raw = new Uint8Array(width * height * 4), result = new Uint8ClampedArray(raw.length)
  gl.readPixels(originX, viewportHeight - originY - height, width, height, gl.RGBA, gl.UNSIGNED_BYTE, raw)
  for (let y = 0; y < height; y++) result.set(raw.subarray((height - y - 1) * width * 4, (height - y) * width * 4), y * width * 4)
  gl.deleteBuffer(buffer); gl.deleteTexture(texture); gl.deleteProgram(program); gl.deleteShader(vertex); gl.deleteShader(fragment)
  gl.getExtension("WEBGL_lose_context")?.loseContext()
  return result
}

import * as React from "react"
import "./minecraft-surface.css"

type Sprite = { width: number; height: number; border: { left: number; top: number; right: number; bottom: number }; stretch: boolean; image: string; pieces: readonly string[] }

function MinecraftSurface({ sprite }: { sprite: Sprite }) {
  const widths = [sprite.border.left, sprite.width - sprite.border.left - sprite.border.right, sprite.border.right]
  const heights = [sprite.border.top, sprite.height - sprite.border.top - sprite.border.bottom, sprite.border.bottom]
  return <span aria-hidden="true" className="mc-surface" style={{
    gridTemplateColumns: `calc(${widths[0]} * var(--mc-pixel)) minmax(0, 1fr) calc(${widths[2]} * var(--mc-pixel))`,
    gridTemplateRows: `calc(${heights[0]} * var(--mc-pixel)) minmax(0, 1fr) calc(${heights[2]} * var(--mc-pixel))`,
  } as React.CSSProperties}>
    {sprite.pieces.map((piece, index) => <span key={index} style={{ backgroundImage: piece,
      backgroundSize: sprite.stretch && (index % 3 === 1 || Math.floor(index / 3) === 1) ? "100% 100%" : `calc(${widths[index % 3]} * var(--mc-pixel)) calc(${heights[Math.floor(index / 3)]} * var(--mc-pixel))`,
    }} />)}
  </span>
}
export { MinecraftSurface }

@layer theme, base, components, utilities;
@layer components {
  .mc-surface {
    position: absolute;
    inset: 0;
    display: grid;
    pointer-events: none;
    image-rendering: pixelated;
  }
  .mc-surface > span { background-repeat: repeat; }
}

import * as React from "react"
import { minecraftGlyphs } from "./minecraft-font"
import "./minecraft-text.css"

function MinecraftText({ children, className }: { children: React.ReactNode; className?: string }) {
  if ((typeof children !== "string" && typeof children !== "number") || !/^[\x20-\x7e]*$/.test(String(children))) return <span className={className}>{children}</span>
  const text = String(children)
  return <span className={`mc-bitmap ${className ?? ""}`}>
    <span className="mc-text-pixels" aria-hidden="true">{Array.from(text, (char, index) => {
      const [x, y, advance] = minecraftGlyphs[char.charCodeAt(0) - 32]
      return <span key={index} className="mc-glyph" style={{ "--mc-glyph-x": x, "--mc-glyph-y": y, "--mc-advance": advance, visibility: char === " " ? "hidden" : undefined } as React.CSSProperties} />
    })}</span>
    <span className="mc-text-accessible">{text}</span>
  </span>
}
export { MinecraftText }

@layer theme, base, components, utilities;
@import "./minecraft-text-assets.css";
@layer components {
  .mc-bitmap { display: inline-flex; image-rendering: pixelated; --mc-pixel: calc(1px * var(--mc-scale, 2)); }
  .mc-bitmap > .mc-text-pixels { display: inline-flex; filter: drop-shadow(var(--mc-pixel) var(--mc-pixel) 0 var(--mc-shadow, #3f3f3f)); }
  .mc-bitmap .mc-glyph {
    display: block;
    width: calc(var(--mc-advance) * var(--mc-pixel));
    height: calc(8 * var(--mc-pixel));
    flex-shrink: 0;
    background-color: var(--mc-ink, #fff);
    mask-image: var(--mc-ascii-atlas);
    mask-size: calc(var(--mc-atlas-size) * var(--mc-pixel)) calc(var(--mc-atlas-size) * var(--mc-pixel));
    mask-position: calc(-1 * var(--mc-glyph-x) * var(--mc-pixel)) calc(-1 * var(--mc-glyph-y) * var(--mc-pixel));
    mask-repeat: no-repeat;
  }
  .mc-bitmap > .mc-text-accessible { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
}
